from itertools import permutations

def lis_length(perm):
    # patience sorting
    tails = []
    for x in perm:
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo+hi)//2
            if tails[mid] < x:
                lo = mid+1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
    return len(tails)

count = 0
for p in permutations(range(1,9)):
    if lis_length(p) <= 3 and lis_length(p[::-1]) <= 3:
        count += 1
print(count)
