    mono_g = (lcm_exp[0] - lt_g[0], lcm_exp[1] - lt_g[1])

    cf = f[lt_f]
    cg = g[lt_g]

    p1 = poly_mul_mono(f, mono_f, cg)
    p2 = poly_mul_mono(g, mono_g, cf)
    return poly_sub(p1, p2)

